// Del BCE solo los comunicados (/press/pr/): discursos, entrevistas y blog llevan nombre de autor y sus terminos piden permiso escrito
const PERMITIDO = (link) => !/ecb\.europa\.eu/i.test(link) || /ecb\.europa\.eu\/+press\/pr\//i.test(link);
return $input.all().filter((item) => PERMITIDO((item.json || {}).link || '')).map(item => {
  const j = item.json || {};
  const raw = j.contentSnippet || j.content || j.description || j.summary || j.title || '';
  const contentSnippet = String(raw).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  const pubDate = j.isoDate || j.pubDate || j.pubdate || j.date || '';
  const link = j.link || '';
  // R1 -- ninguno de los nodos RSS etiquetaba su fuente,
  // asi que las dos llegaban como 'RSS' generico y la atribucion visible que exige la
  // auditoria legal no podia decir CUAL fuente. Se deriva del dominio del propio link, sin
  // anadir un nodo nuevo al canvas.
  let fuente = j.fuente || '';
  if (!fuente) {
    if (/cftc\.gov/i.test(link)) fuente = 'CFTC';
    else if (/investing\.com/i.test(link)) fuente = 'Investing.com';
    else if (/cnbc\.com/i.test(link)) fuente = 'CNBC';
    else if (/prnewswire\.com/i.test(link)) fuente = 'PR Newswire';
    else if (/federalreserve\.gov/i.test(link)) fuente = 'Reserva Federal';
    else if (/sec\.gov\/Archives\/edgar\//i.test(link)) fuente = 'EDGAR';
    else if (/sec\.gov/i.test(link)) fuente = 'SEC';
    else if (/occ\.gov/i.test(link)) fuente = 'OCC';
    else if (/fdic\.gov/i.test(link)) fuente = 'FDIC';
    else if (/globenewswire\.com/i.test(link)) fuente = 'GlobeNewswire';
    else if (/ecb\.europa\.eu/i.test(link)) fuente = 'BCE';
    else if (/eia\.gov/i.test(link)) fuente = 'EIA';
    else if (/bea\.gov/i.test(link)) fuente = 'BEA';
  }
  return { json: {
    title: String(j.title || '').trim(),
    link: link,
    contentSnippet: contentSnippet,
    pubDate: pubDate,
    fuente: fuente
  }};
});

