// el articulo se salta (se reintenta en la corrida siguiente) en vez de darse por nuevo.
const titulares = $('Titulares recientes').item.json;
if (titulares.statusCode !== 200 || !Array.isArray(titulares.body)) {
  return [{ json: { es_duplicado: true, titulo_similar: null, motivo: 'sin titulares recientes' } }];
}
let raw = $json.output?.[0]?.content?.[0]?.text ?? $json.choices?.[0]?.message?.content ?? $json.message?.content ?? $json.text;
let data = null;
try {
  if (typeof raw === 'string') data = JSON.parse(raw);
  else if (raw && typeof raw === 'object') data = raw;
} catch (e) {
  data = null;
}
if (!data || typeof data.es_duplicado !== 'boolean') {
  return [{ json: { es_duplicado: true, titulo_similar: null, motivo: 'veredicto ilegible' } }];
}
return [{ json: { es_duplicado: data.es_duplicado, titulo_similar: data.titulo_similar || null } }];

