const FRASE_FINAL = 'Para más noticias, visita el enlace de la bio.';
const EMOJI = { 1: '₿', 2: '💱', 3: '🛢️', 4: '📈' };
const ETIQUETA_CAT = { 1: '#Cripto', 2: '#Forex', 3: '#MateriasPrimas', 4: '#Mercados' };
const ETIQUETA_ACTIVO = {
  BTC: '#Bitcoin', ETH: '#Ethereum', SOL: '#Solana', XRP: '#XRP', ADA: '#Cardano', DOGE: '#Dogecoin', BNB: '#BNB',
  XAUUSD: '#Oro', XAGUSD: '#Plata', PLATINUM: '#Platino', PALLADIUM: '#Paladio', COPPER: '#Cobre', WTI: '#Petróleo', BRENT: '#Petróleo',
  NG: '#GasNatural', CORN: '#Maíz', WHEAT: '#Trigo', SUGAR: '#Azúcar', COFFEE: '#Café',
  EURUSD: '#EURUSD', GBPUSD: '#GBPUSD', USDJPY: '#USDJPY', USDCHF: '#USDCHF', USDCAD: '#USDCAD', AUDUSD: '#AUDUSD', NZDUSD: '#NZDUSD', EURGBP: '#EURGBP', EURJPY: '#EURJPY', GBPJPY: '#GBPJPY',
  SPX: '#SP500', NDX: '#Nasdaq', DJI: '#DowJones', DXY: '#Dólar', VIX: '#VIX', US10Y: '#Bonos', DAX: '#DAX', CAC40: '#CAC40', FTSE: '#FTSE', NIKKEI: '#Nikkei', HSI: '#HangSeng', ESTX50: '#EuroStoxx',
};
// Fuera cualquier cosa que X convierta en enlace (URL o dominio suelto, p. ej. «Nasdaq.com»), y @ y # sueltos (menciones o etiquetas por accidente)
const TLD = '(?:com|net|org|io|co|app|ai|info|biz|gov|edu|ly|me|tv|xyz|dev|news|finance|bank|us|es|mx|uk|eu|ar|cl|br|de|fr)';
const limpiar = (t) => String(t == null ? '' : t)
  .replace(/https?:\/\/\S+|www\.\S+/gi, ' ')
  .replace(new RegExp('\\b([\\p{L}\\d-]+)\\.' + TLD + '\\b', 'giu'), '$1')
  .replace(/[@#]/g, '')
  .replace(/\s+/g, ' ')
  .trim();
