const recortar = (t, max) => {
  if (peso(t) <= max) return t;
  let o = t;
  // se corta por palabras completas (nunca a media palabra)
  while (o.length > 1 && peso(o + '…') > max) {
    const i = o.lastIndexOf(' ');
    o = i > 0 ? o.slice(0, i) : o.slice(0, -1);
  }
  return o.replace(/[\s,.;:–-]+$/, '') + '…';
};
const MAX = 275;
const emoji = EMOJI[a.categoria] || '📰';
const titulo = limpiar(a.titulo);
let resumen = limpiar(a.resumen);
if (resumen.toLowerCase() === titulo.toLowerCase()) resumen = '';
if (resumen.length < 20) resumen = ''; // un contexto de menos de 20 letras no aporta
const etiquetas = [];
for (const s of Array.isArray(a.activos) ? a.activos : []) {
  const t = ETIQUETA_ACTIVO[s];
  if (t && !etiquetas.includes(t)) etiquetas.push(t);
  if (etiquetas.length >= 2) break;
}
const cat = ETIQUETA_CAT[a.categoria];
if (cat && etiquetas.length < 2 && !etiquetas.includes(cat)) etiquetas.push(cat);
const armar = (t, r) => [emoji + ' ' + t, r, etiquetas.join(' '), FRASE_FINAL].filter(Boolean).join('\n\n');
let tit = recortar(titulo, 140);
let res = resumen;
let texto = armar(tit, res);
if (peso(texto) > MAX) {
  // primero se recorta el contexto; un contexto de menos de 20 letras no aporta y se quita
  res = res ? recortar(res, Math.max(0, peso(res) - (peso(texto) - MAX))) : '';
  if (res.length < 40) res = ''; // un contexto que queda en un trozo corto es peor que ninguno
  texto = armar(tit, res);
}
if (peso(texto) > MAX) {
  tit = recortar(titulo, Math.max(20, 140 - (peso(texto) - MAX)));
  texto = armar(tit, res);
}
if (peso(texto) > MAX) texto = armar(recortar(titulo, 100), '');
return { json: { ...a, texto, largo: peso(texto), publicar: leer(() => $env.X_PUBLICAR_ACTIVO) === 'true' } };

// Resultado de la publicacion: 201 + id = publicada. Cualquier otra cosa es un fallo con motivo legible (el flujo del sitio no se ve afectado).
const r = $json || {};
const previo = $('X - Media id').item.json;
const estado = Number(r.statusCode || 0);
let cuerpo = r.body !== undefined ? r.body : r.data;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (_) { /* queda como texto */ } }
const id = cuerpo && cuerpo.data && cuerpo.data.id ? String(cuerpo.data.id) : null;
let error = '';
if (!(estado === 201 && id)) {
  // n8n entrega los fallos anteriores a la peticion (credencial sin token, sin red) en `details.message`; `error` llega como objeto vacio
  let detalle = (cuerpo && (cuerpo.detail || cuerpo.title)) || (r.details && r.details.message) || r.error || '';
  if (detalle && typeof detalle !== 'string') detalle = JSON.stringify(detalle);
  error = 'X respondio ' + (estado || 'sin respuesta') + (detalle ? ': ' + String(detalle).slice(0, 160) : '');
  if (estado === 402) error += ' (sin saldo en la cuenta de desarrollador de X)';
  else if (estado === 401 || estado === 403) error += ' (credencial sin permiso o caducada)';
  else if (estado === 429) error += ' (limite de frecuencia)';
  if (/unable to sign without access token/i.test(String(detalle))) error = 'credencial de X sin conectar (falta el token de acceso): abrir «X (grizzlytraders)» en n8n y pulsar Connect';
}
return { json: { ok: !error, xId: id, error, texto: previo.texto, postId: previo.postId, conImagen: !!previo.conImagen, errorImagen: previo.errorImagen || '' } };

// Resultado de la subida de la portada. Con id de imagen, la publicacion lleva portada; SIN id (cualquier fallo) se publica solo el texto: la portada nunca
// debe impedir una publicacion. Se recuperan los datos del articulo del nodo «Armar texto X».
const previo = $('Armar texto X').item.json;
const r = $json || {};
const estado = Number(r.statusCode || 0);
let cuerpo = r.body !== undefined ? r.body : r.data;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (_) { /* queda como texto */ } }
const id = cuerpo && cuerpo.data && cuerpo.data.id ? String(cuerpo.data.id) : '';
let errorImagen = '';
if (!id) {
  let detalle = (cuerpo && typeof cuerpo === 'object' && (cuerpo.detail || cuerpo.title)) || (r.details && r.details.message) || r.error || '';
  if (detalle && typeof detalle !== 'string') detalle = JSON.stringify(detalle);
  errorImagen = 'portada no subida (X respondio ' + (estado || 'sin respuesta') + (detalle ? ': ' + String(detalle).slice(0, 120) : '') + ')';
  if (/unable to sign without access token/i.test(String(detalle))) errorImagen = 'portada no subida (credencial de X sin conectar (falta el token de acceso): abrir «X (grizzlytraders)» en n8n y pulsar Connect)';
}
return { json: { ...previo, mediaId: id, conImagen: id !== '', errorImagen } };

// Firma OAuth 1.0a (HMAC-SHA1) de la subida de la portada a X. El permiso `media.write` de OAuth 2.0 no se concede a esta app (la subida da 403), pero el mismo
// endpoint acepta OAuth 1.0a con el token de acceso de la propia cuenta. Las cuatro claves viven solo en variables de entorno del servidor ($env), nunca en el flujo.
// Sin claves o ante cualquier fallo, `authX` queda vacío: la subida falla y la publicación sale solo con texto (la portada nunca impide publicar).
